-- Preguntas frecuentes para la app SIN internet (SQLite). Búsqueda:
-- SELECT f.* FROM faq_fts JOIN faq f ON f.id = faq_fts.rowid WHERE faq_fts MATCH 'pesca* OR comer*' ORDER BY bm25(faq_fts) LIMIT 3;
BEGIN TRANSACTION;
CREATE TABLE faq (id INTEGER PRIMARY KEY, pregunta TEXT, respuesta TEXT, fuente TEXT, tema TEXT, audio TEXT);
PRAGMA writable_schema=ON;
CREATE TABLE 'faq_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID;
CREATE TABLE 'faq_fts_content'(id INTEGER PRIMARY KEY, c0, c1);
CREATE TABLE 'faq_fts_data'(id INTEGER PRIMARY KEY, block BLOB);
CREATE TABLE 'faq_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB);
CREATE TABLE 'faq_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID;
PRAGMA writable_schema=OFF;
COMMIT;
